// Generated by `just generate` from `src/plugins/claudetto/slices/advise/lab/advise.test.ts`. Edit the source and run `just generate`.
// Lab tests of the tool `advise`: the registration at session start, and the result of each reply of `model.complete`.
// The stubs record the request of the model, and no model call goes out.
// The file is self-contained, because `just generate` copies it to `tests/` of the plugin, where it cannot import a relative file.

import type { ModelCompleteResult, On, PluginOptions } from "claude-code";
import { type Engine, expect, test } from "claude-code/testing";

declare module "claude-code" {
  interface McpToolInputs {
    mcp__claudetto__advise: { question: string };
  }
}

const USAGE = {
  input_tokens: 10,
  output_tokens: 5,
  cache_read_input_tokens: 0,
  cache_creation_input_tokens: 0,
};
let sessions = 0;
const ON: { options: PluginOptions } = { options: { advisor: "claudetto" } };

const message = (text: string, tools: string[] = []) => ({
  role: "assistant" as "assistant" | "user",
  text,
  toolUses: tools.map((tool, i) => ({
    tool_use_id: `u${i}`,
    tool,
    input: {},
  })),
});

/** Stubs for one test: `reply` is the result of the model, and `history` the messages. The returned list holds the requests of the model and the registered tools. */
const stub = (
  on: On,
  reply: ModelCompleteResult,
  history = [message("hello")],
) => {
  const seen = {
    requests: [] as Record<string, unknown>[],
    tools: [] as string[],
  };
  on("env.get", () => ({ value: undefined }));
  on("session.start", (_$, e) => ({ cwd: e.cwd }));
  on("session.messages", () => ({ value: history }));
  // A new id for each test, because the count of calls of a session is kept in the module.
  sessions += 1;
  const id = `s${sessions}`;
  on("session.id", () => ({ value: id }));
  on("fs.read", () => ({ deny: "missing" }));
  on("tool.register", (_$, e) => {
    seen.tools.push(e.name);
    return { value: { tool: `mcp__claudetto__${e.name}` } };
  });
  on("model.complete", (_$, e) => {
    seen.requests.push({ ...e });
    return { value: reply };
  });
  return seen;
};

const ask = ($: Engine) =>
  $.tool.call({
    tool: "mcp__claudetto__advise",
    question: "Why does it fail?",
  });

const start = ($: Engine) =>
  $.session.start({ cwd: "/work/app", surface: null, isInteractive: false });

test(
  "with the option `builtin`, session start registers no tool",
  { options: { advisor: "builtin" } },
  async ($: Engine, on: On) => {
    const seen = stub(on, { isAnswered: true, text: "x", usage: USAGE });
    await start($);
    expect(seen.tools).toEqual([]);
  },
);

test(
  "with the option `claudetto`, session start registers the tool",
  ON,
  async ($: Engine, on: On) => {
    const seen = stub(on, { isAnswered: true, text: "x", usage: USAGE });
    await start($);
    expect(seen.tools).toEqual(["advise"]);
  },
);

test(
  "an answer gives the advice with the model name and no token counts, and logs the counts for the user",
  ON,
  async ($: Engine, on: On) => {
    const seen = stub(on, {
      isAnswered: true,
      text: "Check the lock.",
      usage: USAGE,
    });
    const logs: string[] = [];
    on("ui.log", (_$, e) => {
      logs.push(e.text);
      return { value: undefined };
    });
    const { result } = await ask($);
    expect(String(result)).toContain("Check the lock.");
    expect(String(result)).toContain("opus");
    expect(String(result)).not.toContain("tokens");
    expect(logs).toEqual(["`advise`: opus used 10 tokens in, 5 tokens out."]);
    expect(seen.requests[0]).toMatchObject({ model: "opus", effort: "high" });
  },
);

test(
  "an `api-error` gives a result with the status",
  ON,
  async ($: Engine, on: On) => {
    stub(on, {
      isAnswered: false,
      reason: "api-error",
      status: 529,
      error: "overloaded",
      usage: USAGE,
    });
    const { result } = await ask($);
    expect(String(result)).toContain("529");
  },
);

test(
  "an `empty-reply` gives a result that names the empty reply",
  ON,
  async ($: Engine, on: On) => {
    stub(on, { isAnswered: false, reason: "empty-reply", usage: USAGE });
    expect(String((await ask($)).result)).toContain("no text");
  },
);

test(
  "an `aborted` result gives a result that names the cut",
  ON,
  async ($: Engine, on: On) => {
    stub(on, { isAnswered: false, reason: "aborted", usage: USAGE });
    expect(String((await ask($)).result)).toContain("cut short");
  },
);

test(
  "the fourth call in one turn gets no model request",
  ON,
  async ($: Engine, on: On) => {
    const used = message("", Array(3).fill("mcp__claudetto__advise"));
    const seen = stub(on, { isAnswered: true, text: "x", usage: USAGE }, [
      { role: "user", text: "go", toolUses: [] },
      used,
    ]);
    expect(String((await ask($)).result)).toContain(
      "no call left in this turn",
    );
    expect(seen.requests).toEqual([]);
  },
);

test(
  "the 21st call in one session gets no model request",
  ON,
  async ($: Engine, on: On) => {
    const seen = stub(on, { isAnswered: true, text: "x", usage: USAGE });
    for (let i = 0; i < 20; i += 1) await ask($);
    expect(String((await ask($)).result)).toContain("in this session");
    expect(seen.requests).toHaveLength(20);
  },
);
